import re

# For left-aligned with space fill: change (.+?) * to ( +)?([^ ]+) .*? 
patterns = {
    "default": r"a (.+?) c",
    "left_v1": r"a( )*([^ ]+).*? c",           # optional leading spaces, then non-space
    "left_v2": r"a\s*([^ ]+).*? c",            # \s* allows any whitespace
}

texts = [
    "a b c",
    "a   b   c",
    "text a hello world c more text",
]

for name, pattern in patterns.items():
    print(f"{name}: {pattern!r}")
    for text in texts:
        m = re.search(pattern, text)
        if m:
            print(f"  search({text!r}) -> group(1)={m.group(1)!r}")
        else:
            print(f"  search({text!r}) -> NO MATCH")
    print()
EOF
